import{_ as e}from"./chunks/popup.KONtJC5w.js";import{_ as o,c as s,o as n,ah as i}from"./chunks/framework.RCw5T9E9.js";const m=JSON.parse('{"title":"Auto run","description":"","frontmatter":{"title":"Auto run"},"headers":[],"relativePath":"options/auto_run.md","filePath":"options/auto_run.md"}'),r={name:"options/auto_run.md"};function a(l,t,h,g,c,p){return n(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="auto-run" tabindex="-1">Auto run <a class="header-anchor" href="#auto-run" aria-label="Permalink to &quot;Auto run&quot;">​</a></h1><blockquote><p><strong>Extension only (Chrome / Edge).</strong> The <strong>Auto Run</strong> block in <strong>Options → General</strong> is <strong>hidden</strong> in <strong>standalone</strong>: a bookmark has no background extension process to decide when to show the panel.</p></blockquote><p><strong>Auto Run</strong> controls <strong>when</strong> the overlay <strong>pill</strong> appears on sites in <strong>overlay</strong> mode. This is <strong>not</strong> the component <strong>blacklist</strong> on <strong>Props</strong> — here we only filter <strong>site origins</strong> (scheme, host, port). Under the title the text is <strong>Enable auto run application</strong>. The only checkbox is <strong>Enable whitelist mode</strong>. There is no switch that turns the lists off.</p><hr><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;Basics&quot;">​</a></h2><p>Rules inspect the page <strong>origin</strong> (scheme, host, port; path is ignored). The placeholder is <code>e.g. https://app.example/ or *localhost*</code>.</p><p>A full <code>http</code> or <code>https</code> URL is compared by origin, ignoring case. The path is dropped. A pattern that contains <code>*</code> is matched against the whole origin, ignoring case: <code>*</code> is any substring, and the pattern must cover the whole origin. A pattern with no <code>*</code> and no scheme must equal the whole origin, so <code>localhost</code> does not match <code>http://localhost:5173</code>. Use <code>*localhost*</code>.</p><p>Empty input and a pattern already in that list are ignored, with no message. Empty lists impose no restriction until you add rows (or enable whitelist mode, below).</p><p>The overlay still <strong>won’t</strong> inject on pages the extension treats as <strong>static without Vue</strong> (separate heuristic). Lists don’t bypass that — see the extension <strong>popup</strong> section.</p><hr><h2 id="site-blacklist" tabindex="-1">Site Blacklist <a class="header-anchor" href="#site-blacklist" aria-label="Permalink to &quot;Site Blacklist&quot;">​</a></h2><p><strong>Site Blacklist</strong> — origins/patterns where the pill <strong>must not</strong> auto-show.</p><ul><li>Add via the field and <strong>Add</strong>, or Enter. The columns are <strong>Name</strong> and <strong>Added</strong>. <strong>Added</strong> is the date only.</li><li>An empty list says <strong>No site in blacklist</strong>.</li><li>Click a row to open <strong>Site Blacklist Details</strong>. The menu is <strong>Edit</strong> and <strong>Delete</strong>.</li><li><strong>Edit</strong> uses the field <strong>Pattern</strong> (placeholder <strong>Origin pattern</strong>). <strong>Save</strong> is disabled while it is blank. The same pattern already on another row is ignored. <strong>Added</strong> in the card is the date and time. Back or Escape closes the card.</li><li>If the current origin <strong>matches any</strong> blacklist row, auto-run overlay is off for that tab.</li></ul><p>Blacklist can combine with whitelist: whitelist is evaluated first when active and non-empty.</p><hr><h2 id="site-whitelist-and-whitelist-mode" tabindex="-1">Site Whitelist and “whitelist mode” <a class="header-anchor" href="#site-whitelist-and-whitelist-mode" aria-label="Permalink to &quot;Site Whitelist and “whitelist mode”&quot;">​</a></h2><p><strong>Enable whitelist mode</strong> shows <strong>Site Whitelist</strong>. The warning on that block is: <strong>When the whitelist is not empty, the application will only run when the page origin (scheme, host including www, port) matches a pattern.</strong></p><ul><li>While the whitelist is <strong>empty</strong>, mode is effectively open — only blacklist (if any) applies.</li><li>Once the whitelist has <strong>at least one</strong> row, auto overlay is <strong>only</strong> allowed on matching origins; everything else is denied <strong>before</strong> blacklist trims further.</li><li>An empty list says <strong>No site in whitelist</strong>. A row opens <strong>Site Whitelist Details</strong>. Add, edit, and delete work like the blacklist. The same pattern in that list is ignored.</li></ul><p>So a <strong>non-empty whitelist</strong> defines “where yes”, <strong>blacklist</strong> subtracts exceptions.</p><hr><h2 id="extension-popup-—-escape-hatch" tabindex="-1">Extension popup — escape hatch <a class="header-anchor" href="#extension-popup-—-escape-hatch" aria-label="Permalink to &quot;Extension popup — escape hatch&quot;">​</a></h2><p><img src="'+e+'" alt="Всплывающее окно"></p><p>The extension icon <strong>popup</strong> exposes two actions (UI labels in English: <strong>Forced Launch</strong>, <strong>Reset Settings</strong>).</p><p><strong>Forced Launch</strong> injects the inspector on the <strong>active tab</strong>, <strong>ignoring</strong> Auto Run lists and the static-site heuristic. Use when lists block all sites or <strong>Options</strong> is unreachable.</p><p><strong>Reset Settings</strong> performs a <strong>full wipe</strong> of saved inspector settings (Auto Run, theming, favorites, etc.). <a href="/qa-tools/docs/ai/settings.html">Options → AI</a> stays. Last resort if configuration locks you out — there is <strong>no</strong> undo without a backup export.</p><p>If you rely on a strict whitelist, keep at least one URL you use to open <strong>Options</strong>, or remember <strong>Forced Launch</strong> / <strong>Reset Settings</strong>.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/install.html#storage">Installation → Where settings are stored</a></li><li><a href="/qa-tools/docs/extension.html">Browser extension</a></li></ul>',29)])])}const w=o(r,[["render",a]]);export{m as __pageData,w as default};
